set role service_role;
select th.assert((select outcome from public.th_c26_outcome where who = 'holder') = 'removed', 'the removal committed');
select th.assert((select outcome from public.th_c26_outcome where who = 'contender') = 'refused:card_payment_stale_version', 'the confirmation was refused: the matching state it was made on no longer exists');
select th.assert(not exists (select 1 from public.card_payment_decisions where kind = 'pair'), 'and it wrote no decision');
select th.assert((select coalesce(array_agg(a_plaid_transaction_id order by a_plaid_transaction_id), '{}') from public.card_payment_decisions where kind = 'destination_removed_card' and superseded_by is null) = array['c26-q'], 'the removal preserved the one known destination; the unconfirmed payment got none');
select th.assert((public.get_card_payment_states('00000000-0000-0000-0000-0000000000aa')->>'fresh')::boolean and (select evaluated_version = input_version from public.card_payment_eval_versions where user_id = '00000000-0000-0000-0000-0000000000aa'), 'fresh: the refused confirmation changed no input after the removal''s evaluation');
select th.assert((select (l->>'state') || '/' || (l->>'reason') || '/' || coalesce(l->>'effectCents', 'null') from (select l from jsonb_array_elements(public.get_card_payment_states('00000000-0000-0000-0000-0000000000aa')->'legs') l where (l->>'transactionId')::uuid = (select id from public.transactions where plaid_transaction_id = 'c26-q')) x(l)) = 'untracked/removed_card/-6000', 'the converted payment counts as leaving the tracked accounts');
select th.assert((select (l->>'state') || '/' || (l->>'reason') || '/' || coalesce(l->>'effectCents', 'null') from (select l from jsonb_array_elements(public.get_card_payment_states('00000000-0000-0000-0000-0000000000aa')->'legs') l where (l->>'transactionId')::uuid = (select id from public.transactions where plaid_transaction_id = 'c26-p')) x(l)) = 'unresolved/no_candidate/null', 'the payment the user had not yet confirmed is unresolved, never matched to a deleted leg');
